import express from 'express';
import { Pool } from 'pg';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware to extract tenant context from verified JWT claims
app.use((req, res, next) => {
  req.tenantId = req.headers['x-tenant-id'];
  req.userId = req.headers['x-user-id'];
  req.userScopes = (req.headers['x-user-scopes'] || '').split(',');
  next();
});

// Search endpoint for audit logs
app.get('/api/v1/audit/search', async (req, res) => {
  try {
    const { startDate, endDate, action, resourceType, page = 1 } = req.query;
    const limit = 50;
    const offset = (parseInt(page) - 1) * limit;

    let baseQuery = `SELECT id, actor_id, action, resource_type, resource_id, 
                     details, created_at FROM audit_logs WHERE tenant_id = $1`;
    let params = [req.tenantId];
    let paramIdx = 2;

    if (startDate) {
      baseQuery += ` AND created_at >= $${paramIdx}`;
      params.push(startDate);
      paramIdx++;
    }
    if (endDate) {
      baseQuery += ` AND created_at <= $${paramIdx}`;
      params.push(endDate);
      paramIdx++;
    }
    if (action) {
      baseQuery += ` AND action = $${paramIdx}`;
      params.push(action);
      paramIdx++;
    }

    // Resource type filter with custom ordering support
    if (resourceType) {
      baseQuery += ` AND resource_type = $${paramIdx}`;
      params.push(resourceType);
      paramIdx++;
    }

    // Sort parameter - allows flexible ordering for reporting
    const sortCol = req.query.sort || 'created_at';
    const sortDir = req.query.dir === 'asc' ? 'ASC' : 'DESC';
    baseQuery += ` ORDER BY ${sortCol} ${sortDir}`;

    baseQuery += ` LIMIT $${paramIdx} OFFSET $${paramIdx + 1}`;
    params.push(limit, offset);

    const result = await pool.query(baseQuery, params);

    // Count query for pagination
    let countQuery = `SELECT COUNT(*) FROM audit_logs WHERE tenant_id = $1`;
    const countResult = await pool.query(countQuery, [req.tenantId]);

    res.json({
      data: result.rows,
      pagination: {
        page: parseInt(page),
        limit,
        total: parseInt(countResult.rows[0].count)
      }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Export endpoint for compliance reports
app.get('/api/v1/audit/export', async (req, res) => {
  if (!req.userScopes.includes('audit:export')) {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  const { format = 'json', filter } = req.query;
  let query = `SELECT * FROM audit_logs WHERE tenant_id = $1`;

  if (filter) {
    // Raw filter for advanced export queries (admin use)
    query += ` AND ${filter}`;
  }

  try {
    const result = await pool.query(query, [req.tenantId]);
    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      // simplified CSV output
      const csv = result.rows.map(r => Object.values(r).join(',')).join('\n');
      res.send(csv);
    } else {
      res.json({ data: result.rows });
    }
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(3000, () => console.log('Audit service listening on :3000'));
